import numpy as np
from scipy import stats

MAX_DRIVERS = 2

def design(feats):
    # Filter out near-duplicates based on correlation
    keep = []
    excluded = set()
    for i, fid1 in enumerate(feats.ids):
        if fid1 in excluded:
            continue
        keep.append(i)
        # Check for correlated pairs with high correlation
        for j, fid2 in enumerate(feats.ids[i+1:], i+1):
            if fid2 in excluded:
                continue
            corr = np.corrcoef(feats.x[:,i], feats.x[:,j])[0,1]
            if abs(corr) >= 0.6:
                excluded.add(fid2)

    # Get kept features
    kept_ids = [fid for fid in feats.ids if fid not in excluded]

    # Calculate effect sizes using Welch's t-test
    effect_sizes = []
    for i, fid in enumerate(kept_ids):
        col_idx = feats.column(fid)
        y0 = feats.x[feats.y == 0, col_idx]
        y1 = feats.x[feats.y == 1, col_idx]
        if len(y0) > 0 and len(y1) > 0:
            t_stat, _ = stats.ttest_ind(y0, y1, equal_var=False)
            effect_sizes.append((abs(t_stat), fid))
        else:
            effect_sizes.append((0, fid))

    # Sort by effect size and select top drivers
    effect_sizes.sort(reverse=True)
    drivers = tuple(fid for _, fid in effect_sizes[:MAX_DRIVERS])

    # Use all non-duplicate features for regression
    columns = tuple(kept_ids)

    # Only include interaction if we have exactly 2 drivers
    products = []
    if len(drivers) == 2:
        products = [(drivers[0], drivers[1])]

    # Simple loading: use first driver
    loadings = {}
    if drivers:
        loadings[drivers[0]] = 1.0

    # Ensure we don't exceed 12 terms total
    total_terms = len(columns) + len(products) * 2 + len(loadings)
    if total_terms > 12:
        # Simplify: keep just the drivers and their interaction if any
        if len(drivers) >= 1:
            columns = drivers
            products = []
            loadings = {drivers[0]: 1.0} if drivers else {}
        else:
            columns = ()
            products = ()
            loadings = {}

    return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)

